css:
.aa-stage, .hk-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #0f1630; }
.aa-home, .hk-home { position: absolute; right: 14px; top: 12px; font-size: 19px !important; padding: 8px 14px !important; }
.aa-out, .hk-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 2.2em; }
.aa-out small { display: block; margin-top: 4px; font-size: 18px; color: var(--ink-2); }
.aa-side { display: flex; flex-wrap: wrap; gap: 8px; }
.aa-side button { font: 700 19px/1.2 var(--f-body); padding: 8px 12px; border: 2px solid #2f9e5b; border-radius: 10px; background: #eaf7ee; color: var(--ink); cursor: grab; touch-action: none; }
.aa-side button small { font-weight: 600; color: #2f7a4a; }
.aa-side button[aria-pressed="true"] { background: #2f9e5b; color: #fff; }
.aa-side button[aria-pressed="true"] small { color: #e6ffe9; }
.aa-ghost { position: fixed; z-index: 50; transform: translate(-50%, -50%); pointer-events: none; font: 800 20px var(--f-body); background: #5cc77a; color: #0f1630; padding: 6px 12px; border-radius: 999px; box-shadow: 0 4px 12px rgba(0,0,0,.3); }
.hk-kind button { font-size: 19px; }
.hk-table { width: 100%; border-collapse: collapse; font-size: 19px; }
.hk-table th, .hk-table td { border: 1.5px solid var(--rule); padding: 4px 8px; text-align: left; }
.hk-table thead th, .hk-table tbody th { background: color-mix(in srgb, var(--accent) 12%, #fff); white-space: nowrap; }
.hk-zoom { position: absolute; left: 14px; bottom: 12px; display: flex; align-items: center; gap: 0; background: rgba(15,22,48,.85); border: 1.5px solid #ffd84d; border-radius: 999px; padding: 6px 12px; color: #ffd84d; font: 700 15px var(--f-body); }
.hk-zoom i { width: 22px; height: 22px; border-radius: 50%; background: #5cc77a; display: inline-block; }
.hk-zoom i + i, .hk-zoom b + i { margin-left: 4px; box-shadow: -6px 0 0 -8px #ffd84d; }
.hk-zoom b { margin: 0 6px; font-weight: 700; }
.hk-zoom span { margin-left: 8px; color: #cfe; }

